}

/** H5 环境是否为 Android（整改通知书走应用内预览，避免下载链路与 401 跳首页）。 */
export function isAndroidH5Agent(ua: string): boolean {
  return /Android/i.test(ua)
}

/** 组装带鉴权头的 API 绝对 URL（path 为 /v2.0/... 相对路径）。 */
export function buildAuthedApiUrl(path: string): string {
  const apiBase = getApiBase()
  if (!apiBase) throw new Error('真实接口未配置：请设置 VITE_API_BASE_URL')
  return `${apiBase.replace(/\/+$/, '')}/${path.replace(/^\/+/, '')}`
}

/** 带鉴权 fetch PDF 等为 blob（供应用内预览页使用）。 */
export async function fetchAuthedBlob(path: string): Promise<Blob> {
  const url = buildAuthedApiUrl(path)
  const headers: Record<string, string> = { 'zhi-project-id': getProjectId() }
  const token = getToken()
  if (token) headers.Authorization = `Bearer ${token}`
  const resp = await fetch(url, { headers })
  if (!resp.ok) {
    let msg = `预览失败（HTTP ${resp.status}）`
    try {
      const j = await resp.json()
      if (j && j.msg) msg = String(j.msg)
    } catch { /* 非 JSON */ }
    throw new Error(msg)
  }
  return resp.blob()
}

